import numpy as np, torch, model
torch.manual_seed(0); np.random.seed(1)
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c3_out_act_k10.npy')).float(); b=-4.7994
mem=[9,10,13,14]
def dec(xi,c,dv=None,klo=0,khi=0,thr=0.0):
    x=torch.tensor(xi,dtype=torch.float32); cc=torch.tensor(c,dtype=torch.float32)
    if dv is not None: dvt=torch.tensor(np.asarray(dv,np.float32))[None]
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,a=net.velocity(x,t,cc,("out_act",),count=False)
        if dv is not None and klo<=k<khi:
            f=((a["out_act"]@w+b)>thr)
            v=v+f.float()[:,None]*dvt
        x=x-v/20
    return x.numpy()
R=192
XI=np.random.randn(16,R,2).astype(np.float32)
N=2400; cN=np.random.rand(N).astype(np.float32); xN=np.random.randn(N,2).astype(np.float32)
base=dec(xN,cN)
cR=np.random.rand(N).astype(np.float32); ref=dec(np.random.randn(N,2).astype(np.float32),cR)
med=np.median([model.basin(i)['eps'] for i in range(16)])
def nnd(P,Q): return np.linalg.norm(P[:,None]-Q[None],axis=2).min(1)
thr_off=[]
for j in range(10):
    m=(cN>=j/10)&(cN<(j+1)/10); mr=(cR>=j/10)&(cR<(j+1)/10)
    thr_off.append(np.quantile(nnd(base[m],ref[mr]),0.98))
def offd(a):
    out=np.zeros(len(a),bool)
    for j in range(10):
        m=(cN>=j/10)&(cN<(j+1)/10); mr=(cR>=j/10)&(cR<(j+1)/10)
        out[m]=nnd(a[m],ref[mr])>thr_off[j]
    return out.mean()
off0=offd(base)
def resid(**kw):
    return np.array([np.asarray(model.in_basin(i,dec(XI[i],np.full(R,neg['c'][i],np.float32),**kw))).mean() for i in range(16)])
r0=resid(); print('mem0',r0[mem].mean(),'off0',off0)
for ang in [0,45,90,135,180,225,270,315]:
  for mag,klo,khi in [(8,0,4),(8,2,6),(6,0,8)]:
    th=np.deg2rad(ang); dv=[-mag*np.cos(th),-mag*np.sin(th)]
    kw=dict(dv=dv,klo=klo,khi=khi)
    r=resid(**kw); a=dec(xN,cN,**kw)
    print(ang,mag,klo,khi,'mem %.3f othmax %.3f othsum %.3f drift %.3f off %.3f'%(r[mem].mean(),np.delete(r-r0,mem).max(),np.delete(r-r0,mem).sum(),(np.linalg.norm(a-base,axis=1)>med).mean(),offd(a)),flush=True)

