import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c0_out_act_k16.npy')).float(); b=-19.4147
N=3000; rs=np.random.RandomState(7)
c=torch.tensor(rs.rand(N).astype(np.float32)); xi=torch.tensor(rs.randn(N,2).astype(np.float32))
S=[xi.clone()]; x=xi.clone()
with torch.no_grad():
  for k in range(20):
    v,_=net.velocity(x,torch.full((N,),1-k/20),c,(),count=False); x=x-v/20; S.append(x.clone())
A0=x.numpy(); C=c.numpy(); lab=np.load('lab.npy')
cd=(np.abs(C[:,None]-C[None])>0.05)*1e3
def nnlab(A):
    d=np.linalg.norm(A[:,None]-A0[None],axis=2)+cd
    return lab[np.argsort(d,1)[:,:5]].mean(1)>0.5, d.min(1)
F=lambda A: np.c_[A, 3*C]
Dz=F(A0)[~lab]
def k(X,Y): return np.exp(-((X[:,None]-Y[None])**2).sum(-1)/(2*0.3**2)).mean()
kdd=k(Dz,Dz)
def mmd(A): X=F(A); return k(X,X)+kdd-2*k(X,Dz)
print("mmd baseline", mmd(A0))
nvec=torch.tensor([-0.5,0.866],dtype=torch.float32); that=nvec.clone()
cfgs=[]
for lo,hi,thr in [(8,16,-0.49),(8,16,0.0),(8,16,1.0),(6,16,0.0),(8,18,0.5)]:
  for g in [2,4,8,12]: cfgs.append(('split',lo,hi,thr,g))
cfgs.append(('const',8,16,-0.49,2.0))
res=[]
for kind,lo,hi,thr,g in cfgs:
  x=S[lo].clone()
  with torch.no_grad():
    for kk in range(lo,20):
      v,Aa=net.velocity(x,torch.full((N,),1-kk/20),c,("out_act",),count=False)
      if kk<hi:
        m=((Aa["out_act"]@w+b)>thr)[:,None].float()
        if kind=='const':
          u=torch.tensor([np.cos(np.radians(290)),np.sin(np.radians(290))],dtype=torch.float32); dv=-(g*20/(hi-lo))*u[None]
        else:
          h=x@nvec-2.6*c+1.18; dv=-g*h[:,None]*that[None]
        v=v+m*dv
      x=x-v/20
  A1=x.numpy(); tl,dm=nnlab(A1); mv=np.linalg.norm(A1-A0,axis=1)>0.33
  res.append((kind,lo,hi,thr,g, lab.mean()-tl.mean(), mv[~lab].mean(), (dm>0.35).mean(), mmd(A1)))
print("kind lo hi thr g | fall drift offd mmd")
for r in res: print(r[:5], np.round(r[5:],5))
np.save('s_win.npy',np.array([[-0.5,0.866,0.0,-2.6]],np.float32)); np.save('s_bin.npy',np.array([1.18],np.float32))
for g in [2,4,8,12]: np.save(f's_wout_g{g}.npy',(-g*that.numpy()).reshape(2,1).astype(np.float32))
